def pluck(arr):
    """
    Return [smallest_even_value, index] for the smallest even value in arr.
    If multiple nodes have the same smallest even value, return the smallest index.
    If there are no even values or arr is empty, return [].
    """
    best_value = None
    best_index = None

    for index, value in enumerate(arr):
        if value % 2 == 0:
            if best_value is None or value < best_value:
                best_value = value
                best_index = index

    if best_value is None:
        return []

    return [best_value, best_index]

