def is_simple_power(x, n):
    """Return True if x is a simple power of n, otherwise False."""
    if x == 1:
        return True

    if n == 1:
        return False

    if n == 0:
        return x == 0

    if n == -1:
        return x == -1

    if n > 1:
        if x <= 0:
            return False

        value = 1
        while value < x:
            value *= n
        return value == x

    # n < -1
    if x == 0:
        return False

    abs_x = abs(x)
    value = 1
    exponent = 0

    while value < abs_x:
        value *= -n
        exponent += 1

    if value != abs_x:
        return False

    if x > 0:
        return exponent % 2 == 0
    else:
        return exponent % 2 == 1
