import re

def valid_date(date):
    if not isinstance(date, str) or not date:
        return False

    if not re.fullmatch(r"[0-9]{2}-[0-9]{2}-[0-9]{4}", date):
        return False

    month = int(date[0:2])
    day = int(date[3:5])

    if month < 1 or month > 12:
        return False

    if day < 1:
        return False

    if month in (1, 3, 5, 7, 8, 10, 12):
        max_day = 31
    elif month in (4, 6, 9, 11):
        max_day = 30
    else:  # month == 2
        max_day = 29

    return day <= max_day
